-- Mississippi had nothing at all. It is the last of the empty states bar
-- Hawaii.
--
-- Two of these very nearly did not arrive: the file was missing a blank line
-- before entries 46 and 86, which glued each onto the stop above and made both
-- vanish. The parser now splits on numbered headings as well as blank lines,
-- because a blank line is a formatting convention and will be got wrong again.
--
-- Tennessee, Alabama and Mississippi are Central time; so are Illinois,
-- Wisconsin and Louisiana. No county exceptions in any of the six.
--
-- 125 stops.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Aden Mounds', 'aden-mounds', 'weird-history', 32.63735, -90.8376, 'Valley Park', 'MS', 'A Coles Creek-era mound complex east of Valley Park where three mounds once framed a plaza along Jeff Davis Bayou. The site is private property; use the Mississippi Mound Trail marker/public roadway and do not enter the archaeological site.', 'roadside', 'https://trails.mdah.ms.gov/aden', null, 'America/Chicago', now()),
  ('Anguilla Mound', 'anguilla-mound', 'weird-history', 32.97255, -90.8413, 'Anguilla', 'MS', 'A surviving rectangular platform mound about 20 feet high, built and used over centuries before European settlement. It is on private property and should be observed only from the public viewing route identified by the Mississippi Mound Trail.', 'roadside', 'https://trails.mdah.ms.gov/anguilla', null, 'America/Chicago', now()),
  ('Arcola Mounds', 'arcola-mounds', 'weird-history', 33.245, -90.8819, 'Arcola', 'MS', 'Only part of a once larger six-mound Mississippian complex survives here, including a platform mound rising more than 30 feet. The remaining earthworks are private, so this is a lawful roadside/viewing stop rather than a walk-on site.', 'roadside', 'https://trails.mdah.ms.gov/arcola', null, 'America/Chicago', now()),
  ('Batesville Mounds', 'batesville-mounds', 'weird-history', 34.34572, -89.92393, 'Batesville', 'MS', 'A rare surviving Woodland-period mound group incorporated into Batesville''s public mound trail area. Several original mounds were destroyed, but the surviving earthworks and interpretive setting make this one of the easier archaeological stops to experience directly.', 'open', 'https://trails.mdah.ms.gov/batesville', null, 'America/Chicago', now()),
  ('Bayou Pierre Mounds', 'bayou-pierre-mounds', 'weird-history', 31.9822, -91.00543, 'Port Gibson', 'MS', 'A prehistoric mound complex near Bayou Pierre where one large platform mound remains clearly visible from Old Mill Road. The property is private, so stay on the public road and use the trail marker as the stop.', 'roadside', 'https://trails.mdah.ms.gov/bayoupierre', null, 'America/Chicago', now()),
  ('Carson Mounds', 'carson-mounds', 'weird-history', 34.2937, -90.6711, 'Stovall', 'MS', 'One of Mississippi''s largest archaeological complexes, once containing seven large mounds, dozens of smaller mounds and an earthen enclosure extending nearly a mile. The surviving mounds are on private property and are a view-only stop.', 'roadside', 'https://trails.mdah.ms.gov/carson', null, 'America/Chicago', now()),
  ('Carter Mounds', 'carter-mounds', 'weird-history', 32.9244, -90.88145, 'Rolling Fork', 'MS', 'Two earthen mounds separated by a plaza survive north of Rolling Fork, representing a community that flourished roughly a thousand years ago. The site is private; use the public roadway/marker and do not cross onto the property.', 'roadside', 'https://trails.mdah.ms.gov/carter', null, 'America/Chicago', now()),
  ('Cary Mounds', 'cary-mounds', 'weird-history', 32.8035, -90.93143, 'Cary', 'MS', 'A Delta mound site associated with Native American settlement in the lower Yazoo Basin. The archaeological remains are privately held, making the Mississippi Mound Trail marker and lawful public-road view the appropriate way to visit.', 'roadside', 'https://trails.mdah.ms.gov/cary', null, 'America/Chicago', now()),
  ('Christmas Mound', 'christmas-mound', 'weird-history', 33.76952, -90.9807, 'Rosedale', 'MS', 'A solitary conical mound about 10 feet tall whose exact construction date remains uncertain, with evidence spanning Late Woodland and Mississippian periods. It stands on private property and should be viewed from the designated public route only.', 'roadside', 'https://trails.mdah.ms.gov/christmas', null, 'America/Chicago', now()),
  ('Dunn Mounds', 'dunn-mounds', 'weird-history', 34.21702, -90.47625, 'Tunica', 'MS', 'Three surviving earthen mounds visible from Mississippi Highway 6, including an unusually elongated oval mound. The site is private; the designated highway viewing area is the stop.', 'roadside', 'https://trails.mdah.ms.gov/dunn', null, 'America/Chicago', now()),
  ('Edgefield Mounds', 'edgefield-mounds', 'weird-history', 34.99215, -90.21558, 'Lake Cormorant', 'MS', 'Three conical Mississippian mounds line an old Mississippi River levee near Lake Cormorant. Soil removal for levee work altered the landscape around them, and visitors should remain on the public road rather than entering the site.', 'roadside', 'https://trails.mdah.ms.gov/edgefield', null, 'America/Chicago', now()),
  ('Emerald Mound', 'emerald-mound', 'weird-history', 31.63542, -91.24767, 'Natchez', 'MS', 'One of the largest Native American ceremonial mounds in the United States, built by ancestors of the Natchez people and covering roughly eight acres. The National Park Service preserves the site and visitors can walk onto the massive earthwork.', 'open', 'https://trails.mdah.ms.gov/emerald', 'https://www.nps.gov/places/emerald-mound.htm', 'America/Chicago', now()),
  ('Evansville Mounds', 'evansville-mounds', 'weird-history', 34.64068, -90.39238, 'Evansville', 'MS', 'A prehistoric mound complex near the unincorporated community of Evansville in Tunica County. The surviving earthworks are part of the Mississippi Mound Trail but remain on private property, so use the public viewing route.', 'roadside', 'https://trails.mdah.ms.gov/evansville', null, 'America/Chicago', now()),
  ('Foster Mounds', 'foster-mounds', 'weird-history', 31.60015, -91.3285, 'Natchez', 'MS', 'Two prehistoric mounds flank a former village/plaza area near Natchez, with a historic house later constructed on one mound. The property is private, so this stop is exterior/view-only from the public route.', 'roadside', 'https://trails.mdah.ms.gov/foster', null, 'America/Chicago', now()),
  ('Glass Mounds', 'glass-mounds', 'weird-history', 32.22827, -90.92747, 'Utica', 'MS', 'A once four-mound Plaquemine-period complex unusually situated in the Mississippi River floodplain. Only portions survive; the site is private and MDAH specifically directs visitors to a designated viewing area.', 'roadside', 'https://trails.mdah.ms.gov/glass', null, 'America/Chicago', now()),
  ('Grace Mounds', 'grace-mounds', 'weird-history', 32.98928, -90.96992, 'Grace', 'MS', 'Two major mounds survive from a five-mound complex near Steele Bayou, including a roughly 40-foot mound visible from nearby roads. The site produced the carved Issaquena Disk used as the Mississippi Mound Trail symbol; the property itself is private.', 'roadside', 'https://trails.mdah.ms.gov/grace', null, 'America/Chicago', now()),
  ('Grand Village of the Natchez Indians / Natchez Tribal History Center', 'grand-village-of-the-natchez-indians-natchez-tribal-history-center', 'weird-history', 31.52565, -91.38067, 'Natchez', 'MS', 'A major Natchez ceremonial center with reconstructed features, preserved mounds, museum exhibits and direct interpretation of Natchez history. Unlike many mound sites, this is a staffed public historic site designed for visitors.', 'open', 'https://trails.mdah.ms.gov/grandvillage', 'https://www.mdah.ms.gov/explore-mississippi/grand-village-natchez-indians', 'America/Chicago', now()),
  ('Hollywood Mounds', 'hollywood-mounds', 'weird-history', 34.77255, -90.3721, 'Tunica', 'MS', 'A large Mississippian ceremonial complex where remote sensing has revealed traces of many vanished boundary mounds around a raised plaza. The surviving mound site should be treated as view-only from public access points.', 'roadside', 'https://trails.mdah.ms.gov/hollywood', null, 'America/Chicago', now()),
  ('Jaketown Mounds', 'jaketown-mounds', 'weird-history', 33.2371, -90.487, 'Belzoni', 'MS', 'A nationally significant archaeological site with evidence of long-distance trade and occupation stretching back thousands of years. Three of the many recorded mounds remain visible from the roadside; stay in designated public areas.', 'roadside', 'https://trails.mdah.ms.gov/jaketown', null, 'America/Chicago', now()),
  ('Johnson Cemetery Mound', 'johnson-cemetery-mound', 'weird-history', 34.74102, -90.3667, 'Tunica', 'MS', 'A prehistoric mound incorporated into a later historic cemetery landscape in the northern Delta. It is part of the Mississippi Mound Trail but should be experienced only from lawful public viewing areas.', 'roadside', 'https://trails.mdah.ms.gov/johnson', null, 'America/Chicago', now()),
  ('Lake George / Holly Bluff Mounds', 'lake-george-holly-bluff-mounds', 'weird-history', 32.81411, -90.683, 'Holly Bluff', 'MS', 'A major prehistoric ceremonial center, also known as the Holly Bluff site, containing a large plaza and surviving platform mounds. The mound group is best observed from the public road and trail marker rather than entered.', 'roadside', 'https://trails.mdah.ms.gov/lakegeorge', null, 'America/Chicago', now()),
  ('Law Mounds', 'law-mounds', 'weird-history', 33.09553, -91.01543, 'Hollandale', 'MS', 'A Mississippian mound complex associated with an abandoned Mississippi River channel near Swan Lake. The surviving main mound is on private property but can be seen from the road leading into the wildlife-refuge area.', 'roadside', 'https://trails.mdah.ms.gov/law', null, 'America/Chicago', now()),
  ('Lessley Mounds', 'lessley-mounds', 'weird-history', 31.15823, -91.44023, 'Woodville', 'MS', 'A prehistoric mound site in Wilkinson County representing the lower Mississippi Valley''s long ceremonial landscape. The mounds are part of the state driving trail but should be viewed from public access only.', 'roadside', 'https://trails.mdah.ms.gov/lessley', null, 'America/Chicago', now()),
  ('Pocahontas Mound', 'pocahontas-mound', 'weird-history', 32.46768, -90.28877, 'Pocahontas', 'MS', 'A surviving Native American mound preserved in a small public roadside park in Pocahontas. It is one of the most straightforward Mound Trail stops for travelers because the mound and marker are intentionally accessible.', 'open', 'https://trails.mdah.ms.gov/pocahontas', null, 'America/Chicago', now()),
  ('Rolling Fork Mounds', 'rolling-fork-mounds', 'weird-history', 32.89603, -90.8772, 'Rolling Fork', 'MS', 'A prehistoric mound site embedded in the modern Rolling Fork landscape, preserving part of the Delta''s much older human history. Use the public marker/viewing area and respect any adjacent private property.', 'roadside', 'https://trails.mdah.ms.gov/rollingfork', null, 'America/Chicago', now()),
  ('Salomon Mounds', 'salomon-mounds', 'weird-history', 34.37697, -90.48927, 'Coahoma', 'MS', 'A once larger Mississippian mound-and-plaza complex near Coahoma, including a large surviving platform mound with a historic cemetery on its summit. MDAH identifies it as private property with a designated viewing area.', 'roadside', 'https://trails.mdah.ms.gov/salomon', null, 'America/Chicago', now()),
  ('Smith Creek Mounds', 'smith-creek-mounds', 'weird-history', 31.14023, -91.5156, 'Woodville', 'MS', 'Three substantial Coles Creek-era ceremonial mounds surround a central plaza near Mississippi Highway 24. The site is archaeologically important but private, so observe it from the highway/public viewing area only.', 'roadside', 'https://trails.mdah.ms.gov/smithcreek', null, 'America/Chicago', now()),
  ('Swan Lake Mounds', 'swan-lake-mounds', 'weird-history', 33.09845, -90.99668, 'Hollandale', 'MS', 'A Native American mound site inside Yazoo National Wildlife Refuge, where two of four original mounds remain visible near the lake. Refuge roads, trails and visitor facilities make this a comparatively accessible archaeological stop; check refuge conditions before going.', 'open', 'https://trails.mdah.ms.gov/swanlake', 'https://www.fws.gov/refuge/yazoo', 'America/Chicago', now()),
  ('Windsor Mounds', 'windsor-mounds', 'weird-history', 31.94599, -91.1265, 'Port Gibson', 'MS', 'Four prehistoric mounds sit roughly half a mile north of the better-known Windsor Ruins, showing that this landscape was significant long before the plantation era. At least one mound is visible from the public road; do not enter private land.', 'roadside', 'https://trails.mdah.ms.gov/windsor', null, 'America/Chicago', now()),
  ('Winterville Mounds', 'winterville-mounds', 'weird-history', 33.48635, -91.064, 'Greenville', 'MS', 'A major Mississippian ceremonial center with a museum and a group of large platform mounds, including one of the tallest in the region. It is a public MDAH site and one of Mississippi''s strongest archaeological road-trip stops.', 'open', 'https://trails.mdah.ms.gov/winterville', 'https://www.mdah.ms.gov/explore-mississippi/winterville-mounds', 'America/Chicago', now()),
  ('Mount Locust Historic Stand', 'mount-locust-historic-stand', 'weird-history', 31.68691, -91.18914, 'Lorman', 'MS', 'One of the last surviving historic stands on the Natchez Trace, where travelers once stopped for food and shelter. As of 2026 the historic structure has a closure tied to structural damage, although the site/grounds have had limited public access; verify conditions before routing a traveler here.', 'limited', 'https://www.nps.gov/places/mount-locust.htm', null, 'America/Chicago', now()),
  ('Sunken Trace', 'sunken-trace', 'weird-history', 31.9702, -90.95558, 'Port Gibson', 'MS', 'A deeply eroded remnant of the Old Natchez Trace where centuries of foot, horse and wagon traffic carved the roadbed below the surrounding ground. A short path from the Parkway pull-off lets visitors walk directly into the historic corridor.', 'open', 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', null, 'America/Chicago', now()),
  ('Rocky Springs Ghost Town Site', 'rocky-springs-ghost-town-site', 'weird-history', 32.08655, -90.79887, 'Rocky Springs', 'MS', 'The remains of a once-prosperous settlement abandoned after disease, erosion, war and economic decline. The NPS site preserves traces of the town, interpretive features and paths through a landscape that has largely returned to woods.', 'open', 'https://www.nps.gov/places/rocky-springs.htm', null, 'America/Chicago', now()),
  ('Rocky Springs Methodist Church', 'rocky-springs-methodist-church', 'weird-history', 32.08977, -90.81348, 'Rocky Springs', 'MS', 'A surviving 1800s church standing near the vanished community of Rocky Springs. Its isolated setting beside a ghost-town landscape gives travelers a rare physical anchor to a town that otherwise almost disappeared.', 'open', 'https://www.nps.gov/places/rocky-springs.htm', null, 'America/Chicago', now()),
  ('Rocky Springs Cemetery', 'rocky-springs-cemetery', 'weird-history', 32.09015, -90.81344, 'Rocky Springs', 'MS', 'The cemetery of the vanished Rocky Springs community, with old stones remaining after most of the town itself disappeared. Treat it as a historic cemetery: visit during lawful access hours, keep to paths and do not disturb graves.', 'open', 'https://www.nps.gov/places/rocky-springs.htm', null, 'America/Chicago', now()),
  ('Grindstone Ford', 'grindstone-ford', 'weird-history', 32.00276, -90.89508, 'Port Gibson', 'MS', 'A Natchez Trace stop where travelers historically crossed Bayou Pierre and where the old road alignment can still be followed on foot. The forested site combines Trace history with the feeling of a route reclaimed by nature.', 'open', 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', null, 'America/Chicago', now()),
  ('Boyd Mounds', 'boyd-mounds', 'weird-history', 32.45313, -90.068, 'Ridgeland', 'MS', 'A Woodland-period mound group beside the Natchez Trace Parkway, preserving ceremonial earthworks built long before the historic Trace. The site has an NPS pull-off/interpretive stop and is meant to be visited from public park land.', 'open', 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', null, 'America/Chicago', now()),
  ('Cypress Swamp', 'cypress-swamp', 'weird-history', 32.57952, -89.87002, 'Canton', 'MS', 'A short Natchez Trace trail loops through a water-filled cypress and tupelo swamp, creating one of the Parkway''s strangest and most atmospheric landscapes. Conditions can be wet and wildlife is present, so remain on the maintained trail.', 'open', 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', null, 'America/Chicago', now()),
  ('Witch Dance', 'witch-dance', 'folklore', 33.91162, -88.939, 'Houston', 'MS', 'A Natchez Trace stop tied to an old regional legend that witches once gathered here to dance, leaving places where grass would not grow. The story is folklore rather than documented fact, but the named NPS site is real and routable.', 'open', 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', null, 'America/Chicago', now()),
  ('Bynum Mounds', 'bynum-mounds', 'weird-history', 33.89847, -88.94808, 'Houston', 'MS', 'Six Woodland-period burial mounds once stood here; surviving mounds and interpretive exhibits preserve evidence of ceremonial life roughly two millennia ago. The site is directly accessible from the Natchez Trace Parkway.', 'open', 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', null, 'America/Chicago', now()),
  ('Jeff Busby / Little Mountain', 'jeff-busby-little-mountain', 'weird-history', 33.41705, -89.26983, 'Ackerman', 'MS', 'A Natchez Trace stop on one of Mississippi''s higher natural points, with a short drive and trail to the top of Little Mountain. Its isolation, old-road setting and elevated view make it a distinctive break from the surrounding Trace landscape.', 'open', 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', null, 'America/Chicago', now()),
  ('Chickasaw Village Site', 'chickasaw-village-site', 'weird-history', 34.27795, -88.74178, 'Tupelo', 'MS', 'An NPS interpretive site focused on Chickasaw life and the Native landscape through which the Natchez Trace passed. A trail crosses the former village area and connects travelers with a history older than the roadway''s later Euro-American use.', 'open', 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', null, 'America/Chicago', now()),
  ('Confederate Gravesites and Old Trace', 'confederate-gravesites-and-old-trace', 'weird-history', 34.36502, -88.67432, 'Tupelo', 'MS', 'A short segment of Old Trace leading to wartime graves associated with the Civil War era. The stop is quiet and historically sensitive; use the established path and treat the graves as a memorial rather than a paranormal attraction.', 'open', 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', null, 'America/Chicago', now()),
  ('Pharr Mounds', 'pharr-mounds', 'weird-history', 34.47098, -88.42052, 'Tupelo', 'MS', 'A group of eight Woodland-period burial mounds spread across a broad field along the Natchez Trace. The NPS pull-off gives travelers a rare panoramic view of multiple ancient earthworks without entering private land.', 'open', 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', null, 'America/Chicago', now()),
  ('Bear Creek Mound', 'bear-creek-mound', 'weird-history', 34.64264, -88.14039, 'Tishomingo', 'MS', 'A prehistoric ceremonial mound preserved near the Alabama end of the Natchez Trace Parkway. The mound and interpretive stop provide one final ancient-site anchor before the Trace leaves Mississippi.', 'open', 'https://www.nps.gov/natr/planyourvisit/places-to-go.htm', null, 'America/Chicago', now()),
  ('The Apron Museum', 'the-apron-museum', 'museums', 34.81195, -88.1903, 'Iuka', 'MS', 'A tiny specialty museum devoted entirely to aprons, domestic history and the stories attached to handmade examples from different eras. It is a genuine niche collection rather than a conventional local-history museum; hours can be limited, so check ahead.', 'limited', 'https://visitmississippi.org/trip-ideas/mississippi-eccentricities-you-have-to-see/', null, 'America/Chicago', now()),
  ('Hattiesburg Pocket Museum', 'hattiesburg-pocket-museum', 'roadside-oddities', 31.32623, -89.29023, 'Hattiesburg', 'MS', 'A miniature outdoor museum hidden in a downtown alley, filled with rotating tiny exhibits, miniature scenes and public art. The alley is designed to be discovered on foot and is accessible without entering a conventional museum building.', 'open', 'https://hattiesburgpocketmuseum.com/', null, 'America/Chicago', now()),
  ('Mississippi Petrified Forest', 'mississippi-petrified-forest', 'weird-history', 32.51438, -90.32299, 'Flora', 'MS', 'A privately operated natural site where ancient petrified logs lie along a walking trail through a 36-million-year-old deposit. The on-site museum and gem/mineral displays push it firmly into OddWay territory without relying on folklore. Coordinate source: https://maps.roadtrippers.com/us/flora-ms/nature/mississippi-petrified-forest', 'open', 'https://www.mspetrifiedforest.com/', null, 'America/Chicago', now()),
  ('Birthplace of Kermit the Frog Museum', 'birthplace-of-kermit-the-frog-museum', 'museums', 33.40009, -90.89068, 'Leland', 'MS', 'A small museum celebrating Jim Henson''s Delta childhood and the local landscape that helped inspire Kermit the Frog. Displays include Muppets-related material and the stop sits beside Deer Creek in Henson''s hometown.', 'open', 'https://visitmississippi.org/trip-ideas/mississippi-eccentricities-you-have-to-see/', null, 'America/Chicago', now()),
  ('Teddy Bear Origin Marker', 'teddy-bear-origin-marker', 'weird-history', 32.90858, -90.87658, 'Rolling Fork', 'MS', 'A roadside marker tied to Theodore Roosevelt''s 1902 Mississippi bear hunt and the story that helped inspire the name "teddy bear." The event''s popular retelling has become part of American toy folklore, making this a compact but meaningful OddWay stop.', 'roadside', 'https://visitmississippi.org/trip-ideas/mississippi-eccentricities-you-have-to-see/', null, 'America/Chicago', now()),
  ('Windsor Ruins', 'windsor-ruins', 'weird-history', 31.94071, -91.12928, 'Port Gibson', 'MS', 'Twenty-three enormous Corinthian columns are nearly all that remain of Windsor, an antebellum mansion destroyed by fire in 1890. The freestanding columns look more like an abandoned classical temple than a former Mississippi house and are one of the state''s strongest ruin stops.', 'open', 'https://visitmississippi.org/things-to-do/architecture/windsor-ruins/', null, 'America/Chicago', now()),
  ('Glenwood Cemetery — Witch of Yazoo Grave', 'glenwood-cemetery-witch-of-yazoo-grave', 'folklore', 32.85156, -90.40048, 'Yazoo City', 'MS', 'Glenwood Cemetery contains the grave associated with the "Witch of Yazoo" legend, a local tale later popularized in Willie Morris''s writing. The grave is real; the witch story is folklore, and visitors should treat the cemetery respectfully.', 'open', 'https://visitmississippi.org/trip-ideas/ghostly-adventures-in-mississippi/', null, 'America/Chicago', now()),
  ('McRaven Tour Home', 'mcraven-tour-home', 'haunted', 32.34604, -90.87192, 'Vicksburg', 'MS', 'A layered historic house assembled in sections dating from the late 1700s through the antebellum era and used during the Civil War. The operator openly offers history tours, haunted tours and paranormal investigations, making the site''s paranormal identity part of its current public use rather than an unsupported rumor. Coordinate source: https://www.atlasobscura.com/places/mcraven-tour-home', 'open', 'https://mcraventourhome.com/', null, 'America/Chicago', now()),
  ('Stuckey''s Bridge', 'stuckeys-bridge', 'folklore', 32.25556, -88.85528, 'Chunky', 'MS', 'A historic bridge associated with the legend of an innkeeper-turned-outlaw named Stuckey and later ghost stories. The folklore is not the same thing as documented history; view the bridge only from lawful public access and do not enter unsafe or posted areas.', 'roadside', 'https://visitmississippi.org/trip-ideas/ghostly-adventures-in-mississippi/', null, 'America/Chicago', now()),
  ('Deason Home', 'deason-home', 'weird-history', 31.60955, -89.19702, 'Ellisville', 'MS', 'A surviving 1800s house tied to the killing of Confederate deserter leader Newton Knight''s opponent Major Amos McLemore during the Civil War. Tours and special events are not always daily, so check current access before routing visitors onto the property.', 'limited', 'https://www.deasonhome.org/', null, 'America/Chicago', now()),
  ('Rose Hill Cemetery — Gypsy Queen Grave', 'rose-hill-cemetery-gypsy-queen-grave', 'folklore', 32.36355, -88.71895, 'Meridian', 'MS', 'A historic cemetery best known to odd-history travelers for the ornate grave of Kelly Mitchell, often called the "Gypsy Queen." The site has accumulated legends and offerings over time; visit as a cemetery and do not disturb memorial items or graves.', 'open', 'https://visitmississippi.org/trip-ideas/ghostly-adventures-in-mississippi/', null, 'America/Chicago', now()),
  ('Mississippi River Basin Model', 'mississippi-river-basin-model', 'weird-history', 32.30606, -90.31894, 'Jackson', 'MS', 'The enormous remains of a hydraulic scale model built by the U.S. Army Corps of Engineers to simulate flooding across the Mississippi River basin. Concrete channels and miniature river systems still spread through the park like the ruins of an abandoned scientific city.', 'open', 'https://www.asce.org/about-civil-engineering/history-and-heritage/historic-landmarks/mississippi-basin-model', null, 'America/Chicago', now()),
  ('Margaret''s Grocery', 'margarets-grocery', 'roadside-oddities', 32.41094, -90.84218, 'Vicksburg', 'MS', 'The visionary-art environment created by Reverend H.D. Dennis around Margaret Rogers Dennis''s former grocery store, covered with hand-built towers, signs, painted masonry and religious messages. The site is undergoing preservation work and should not be treated as freely open; arrange access where required and respect barriers.', 'limited', 'https://spacesarchives.org/explore/search-the-online-collection/margarets-grocery/', null, 'America/Chicago', now()),
  ('Rodney Presbyterian Church and Ghost Town', 'rodney-presbyterian-church-and-ghost-town', 'weird-history', 31.86278, -91.19983, 'Rodney', 'MS', 'A surviving 1830s church anchors the remains of Rodney, once an important Mississippi River town that declined after the river shifted away. Roads can be rough and surrounding property may be private; this is a ghost-town driving stop, not permission to enter abandoned structures. Coordinate source: https://www.hmdb.org/', 'roadside', 'https://www.apps.mdah.ms.gov/Public/prop.aspx?id=20435&view=facts', null, 'America/Chicago', now()),
  ('Mammy''s Cupboard', 'mammys-cupboard', 'roadside-oddities', 31.47801, -91.37129, 'Natchez', 'MS', 'A restaurant built in the form of a giant skirted woman, one of Mississippi''s most recognizable pieces of vernacular roadside architecture. The imagery and name reflect a racist "mammy" stereotype from the Jim Crow era, so the stop is best presented with that historical context rather than as neutral kitsch.', 'open', 'https://www.mammyscupboard.com/', null, 'America/Chicago', now()),
  ('Logtown Ghost Town Marker', 'logtown-ghost-town-marker', 'weird-history', 30.28207, -89.6238, 'Pearlington', 'MS', 'A marker for Logtown, a lumber community founded in 1848 and later emptied when residents were removed from the buffer zone around what became Stennis Space Center. Very little of the town survives, so the interpretive marker is the lawful, routable stop. Secondary source: https://www.mdah.ms.gov/', 'roadside', 'https://www.hmdb.org/', null, 'America/Chicago', now()),
  ('Carter-Calloway Steamboat House', 'carter-calloway-steamboat-house', 'roadside-oddities', 30.41475, -88.82427, 'Ocean Springs', 'MS', 'A private 1906-07 residence whose layered porches, railings and nautical detailing earned it the nickname "Steamboat House." It remains a private home, so OddWay users should view it only from the public street without entering the property.', 'roadside', 'https://www.apps.mdah.ms.gov/Public/', null, 'America/Chicago', now()),
  ('Pascagoula 1973 UFO Encounter Marker', 'pascagoula-1973-ufo-encounter-marker', 'ufos', 30.37133, -88.56103, 'Pascagoula', 'MS', 'A city-installed marker at Lighthouse Park commemorating the 1973 account in which Charles Hickson and Calvin Parker said they were abducted by strange beings while fishing nearby. The marker documents the cultural history of the claim without asserting that the reported encounter occurred as described.', 'open', 'https://www.cityofpascagoula.com/parksrec/page/lighthouse-park', null, 'America/Chicago', now()),
  ('Friendship Oak', 'friendship-oak', 'weird-history', 30.3519, -89.13608, 'Long Beach', 'MS', 'A massive live oak on the University of Southern Mississippi Gulf Park campus estimated to be centuries old and wrapped in local traditions about friendship and good fortune. Its enormous low limbs make it feel almost architectural rather than simply botanical.', 'open', 'https://www.usm.edu/gulf-park/friendship-oak.php', null, 'America/Chicago', now()),
  ('Tishomingo State Park Swinging Bridge', 'tishomingo-state-park-swinging-bridge', 'roadside-oddities', 34.60503, -88.17953, 'Tishomingo', 'MS', 'A suspended pedestrian bridge crossing Bear Creek amid sandstone outcrops and forest in Tishomingo State Park. The bridge is a real public park feature and a visually unusual stop rather than a generic scenic overlook.', 'open', 'https://www.mdwfp.com/parks-destinations/tishomingo', null, 'America/Chicago', now()),
  ('Dockery Farms', 'dockery-farms', 'weird-history', 33.72889, -90.61278, 'Cleveland', 'MS', 'A former cotton plantation widely associated with early Delta blues history and musicians including Charley Patton. Surviving buildings, signs and interpretive material make the site physically meaningful, but access to individual structures/events varies, so check the operator before visiting.', 'limited', 'https://www.dockeryfarms.org/', null, 'America/Chicago', now()),
  ('Delta Blues Museum', 'delta-blues-museum', 'weird-history', 34.20013, -90.57355, 'Clarksdale', 'MS', 'A major museum devoted to Delta blues history, housed in a former railroad depot and containing instruments, photographs, stage material and the reconstructed cabin associated with Muddy Waters. It is one of the strongest anchor stops for the state''s music-history route.', 'open', 'https://www.deltabluesmuseum.org/', null, 'America/Chicago', now()),
  ('B.B. King Museum and Delta Interpretive Center', 'bb-king-museum-and-delta-interpretive-center', 'weird-history', 33.44958, -90.64566, 'Indianola', 'MS', 'A museum built around B.B. King''s life while also interpreting Delta labor, migration, segregation and the regional culture that shaped the blues. King''s grave is on the grounds, making the site both museum and memorial.', 'open', 'https://bbkingmuseum.org/', null, 'America/Chicago', now()),
  ('Robert Johnson Grave — Little Zion Missionary Baptist Church', 'robert-johnson-grave-little-zion-missionary-baptist-church', 'weird-history', 33.5637, -90.21637, 'Greenwood', 'MS', 'The grave at Little Zion is the burial location most widely accepted for blues musician Robert Johnson. Because Johnson has multiple memorial/grave claimant sites in Mississippi, OddWay should identify this one specifically rather than presenting all three as equally certain.', 'open', 'https://msbluestrail.org/', null, 'America/Chicago', now()),
  ('Robert Johnson Memorial — Mount Zion Missionary Baptist Church', 'robert-johnson-memorial-mount-zion-missionary-baptist-church', 'weird-history', 33.39225, -90.31033, 'Morgan City', 'MS', 'A Robert Johnson memorial/cenotaph at Mount Zion, one of several places historically proposed as his burial site. Current scholarship generally favors Little Zion, so this stop should be labeled as a memorial and former grave claimant rather than the confirmed grave.', 'open', 'https://msbluestrail.org/', null, 'America/Chicago', now()),
  ('Robert Johnson Grave Claim — Payne Chapel Memorial Baptist Church', 'robert-johnson-grave-claim-payne-chapel-memorial-baptist-church', 'weird-history', 33.44081, -90.30361, 'Quito', 'MS', 'A headstone erected at Payne Chapel marks another location once claimed as Robert Johnson''s burial place. It is useful as part of the unusual three-grave story surrounding Johnson, but should not be described as the accepted burial site.', 'open', 'https://msbluestrail.org/', null, 'America/Chicago', now()),
  ('The Crossroads Blues Marker', 'the-crossroads-blues-marker', 'folklore', 34.19496, -90.56422, 'Clarksdale', 'MS', 'The famous Highway 61/49 crossroads is associated in popular culture with the legend that Robert Johnson sold his soul to the devil in exchange for musical ability. The crossroads is real; the supernatural bargain is folklore, and the stop should be presented that way.', 'roadside', 'https://msbluestrail.org/', null, 'America/Chicago', now()),
  ('Riverside Hotel Museum', 'riverside-hotel-museum', 'weird-history', 34.19517, -90.57255, 'Clarksdale', 'MS', 'The former G.T. Thomas Afro-American Hospital became a Green Book-era hotel run by the Ratliff family and hosted generations of blues musicians and Black travelers. As of 2026 it is no longer operating as a hotel and functions as a museum/interpretive site with tours arranged by contact.', 'limited', 'https://visitmississippi.org/things-to-do/blues-attractions/riverside-hotel/', null, 'America/Chicago', now()),
  ('Red''s Lounge', 'reds-lounge', 'weird-history', 34.19772, -90.57412, 'Clarksdale', 'MS', 'A small, long-running juke joint closely associated with Clarksdale''s living blues scene. It is an active nightlife venue rather than a daytime museum, so hours and performances should be checked before routing travelers there.', 'limited', 'https://msbluestrail.org/', null, 'America/Chicago', now()),
  ('Highway 61 Blues Museum', 'highway-61-blues-museum', 'weird-history', 33.40573, -90.89755, 'Leland', 'MS', 'A community museum devoted to blues musicians connected to Leland and the surrounding Delta. Current Mississippi Blues Trail information lists it as open by appointment, so travelers should contact it before arrival.', 'limited', 'https://msbluestrail.org/museums', null, 'America/Chicago', now()),
  ('Gateway to the Blues Museum', 'gateway-to-the-blues-museum', 'weird-history', 34.84066, -90.27307, 'Tunica Resorts', 'MS', 'A blues museum and visitor center inside a restored railroad depot along Highway 61. It works especially well as a northern gateway stop before travelers enter the Delta''s denser cluster of juke joints, markers and musician sites.', 'open', 'https://tunicatravel.com/things-to-do/the-blues/gateway/', null, 'America/Chicago', now()),
  ('Club Ebony', 'club-ebony', 'weird-history', 33.44768, -90.64797, 'Indianola', 'MS', 'A historic Black nightclub that hosted major blues, soul and R&B performers and later became closely associated with B.B. King. The B.B. King Museum now stewards the property; public access is tied to scheduled programs/events rather than constant museum hours.', 'limited', 'https://bbkingmuseum.org/club-ebony/', null, 'America/Chicago', now()),
  ('Hollywood Cafe', 'hollywood-cafe', 'weird-history', 34.81733, -90.31555, 'Tunica Resorts', 'MS', 'A Delta restaurant/juke-joint landmark connected to the song "Walking in Memphis" and to the region''s blues-tourism history. Its roadside neon and long-running music associations make it more than a generic restaurant stop.', 'open', 'https://msbluestrail.org/', null, 'America/Chicago', now()),
  ('Blue Front Cafe', 'blue-front-cafe', 'weird-history', 32.64075, -90.36474, 'Bentonia', 'MS', 'Opened in 1948, the Blue Front is one of Mississippi''s best-known surviving juke joints and is closely tied to the Bentonia school of blues. It remains an active cultural site; hours and performances can vary, so check before making it a timed stop.', 'limited', 'https://msbluestrail.org/', null, 'America/Chicago', now()),
  ('GRAMMY Museum Mississippi', 'grammy-museum-mississippi', 'weird-history', 33.74825, -90.73109, 'Cleveland', 'MS', 'A music museum connecting Mississippi''s outsized influence on American music with GRAMMY history, recording technology and interactive exhibits. Its focus spans blues, gospel, rock, country and other genres rather than treating the Delta as a single-style story.', 'open', 'https://www.grammymuseumms.org/', null, 'America/Chicago', now()),
  ('Elvis Presley Birthplace', 'elvis-presley-birthplace', 'weird-history', 34.25997, -88.67994, 'Tupelo', 'MS', 'The two-room house where Elvis Presley was born, preserved with a museum, chapel, church and interpretive grounds. The small scale of the birthplace against the later Elvis mythology makes it a particularly effective music-history stop.', 'open', 'https://elvispresleybirthplace.com/', null, 'America/Chicago', now()),
  ('Tupelo Hardware Company — Elvis''s First Guitar Site', 'tupelo-hardware-company-elviss-first-guitar-site', 'weird-history', 34.25752, -88.70353, 'Tupelo', 'MS', 'The still-operating hardware store where Elvis Presley''s mother bought him his first guitar after he reportedly asked for a rifle. Visitors can stand at the marked location inside the store where the purchase story is interpreted.', 'open', 'https://www.tupelo.net/directory/tupelo-hardware-company/', 'https://tupelohardware.com/', 'America/Chicago', now()),
  ('Jimmie Rodgers Museum', 'jimmie-rodgers-museum', 'weird-history', 32.36898, -88.70013, 'Meridian', 'MS', 'A museum devoted to Meridian native Jimmie Rodgers and his foundational influence on country music, including memorabilia connected to the "Singing Brakeman." Current hours are limited compared with a large daily museum, so check before visiting.', 'limited', 'https://msbluestrail.org/museums', 'https://www.jimmierodgers.com/', 'America/Chicago', now()),
  ('Black Prairie Blues Museum', 'black-prairie-blues-museum', 'weird-history', 33.6067, -88.64833, 'West Point', 'MS', 'A developing museum in a historic downtown bank building focused on Howlin'' Wolf and the blues tradition of Mississippi''s Black Prairie. Its current public schedule is limited to specific days and appointments, so verify hours before routing travelers there. Coordinate source: official museum Google Maps link', 'limited', 'https://www.blackprairiebluesmuseum.com/', null, 'America/Chicago', now()),
  ('Charley Patton Grave', 'charley-patton-grave', 'weird-history', 33.44472, -90.75806, 'Holly Ridge', 'MS', 'The grave of pioneering Delta blues musician Charley Patton, whose recordings and performance style influenced generations of later musicians. It is a cemetery stop and should be approached as a memorial, with normal cemetery etiquette.', 'open', 'https://msbluestrail.org/', null, 'America/Chicago', now()),
  ('Emmett Till Interpretive Center', 'emmett-till-interpretive-center', 'weird-history', 33.9711, -90.3698, 'Sumner', 'MS', 'A museum and interpretive center across from the courthouse where the men accused of murdering Emmett Till were tried and acquitted in 1955. The center places the Till case within the broader history of racial violence, memory and reconciliation in the Mississippi Delta.', 'open', 'https://www.nps.gov/emit/planyourvisit/places-to-go.htm', 'https://www.emmett-till.org/', 'America/Chicago', now()),
  ('Bryant''s Grocery & Meat Market Ruins', 'bryants-grocery-meat-market-ruins', 'weird-history', 33.65249, -90.20877, 'Money', 'MS', 'The deteriorating remains of the store where 14-year-old Emmett Till encountered Carolyn Bryant in August 1955, an event followed by his kidnapping and murder. The ruins are historically important but are not an invitation to enter unstable or private property; view only from lawful public access.', 'roadside', 'https://www.nps.gov/emit/planyourvisit/places-to-go.htm', null, 'America/Chicago', now()),
  ('Graball Landing — Emmett Till National Monument Site', 'graball-landing-emmett-till-national-monument-site', 'weird-history', 33.83178, -90.27023, 'Glendora', 'MS', 'A Mississippi River landing area associated with the recovery of Emmett Till''s body in 1955 and now interpreted as part of the national monument. The road can be rural and conditions may vary, so travelers should remain in designated public areas and avoid adjacent private land.', 'roadside', 'https://www.nps.gov/emit/planyourvisit/places-to-go.htm', null, 'America/Chicago', now()),
  ('Tallahatchie County Courthouse', 'tallahatchie-county-courthouse', 'weird-history', 33.97064, -90.3696, 'Sumner', 'MS', 'The courthouse where the 1955 murder trial following Emmett Till''s killing took place. It remains a functioning civic building as well as a major civil-rights historic site, so interior access depends on courthouse schedules and current visitor arrangements.', 'limited', 'https://www.nps.gov/emit/planyourvisit/places-to-go.htm', null, 'America/Chicago', now()),
  ('Fannie Lou Hamer Memorial Garden', 'fannie-lou-hamer-memorial-garden', 'weird-history', 33.73362, -90.54035, 'Ruleville', 'MS', 'The burial place and memorial garden of voting-rights leader Fannie Lou Hamer, with a bronze statue, Freedom Trail marker and quotations from her life and activism. A dedicated parking area was completed in 2024, making the memorial a practical public stop.', 'open', 'https://www.fannielouhamersamerica.com/driving-tour/fannie-lou-hamer-memorial-gardens', null, 'America/Chicago', now()),
  ('Medgar and Myrlie Evers Home National Monument', 'medgar-and-myrlie-evers-home-national-monument', 'weird-history', 32.34096, -90.21265, 'Jackson', 'MS', 'The home where civil-rights leader Medgar Evers lived with his family and where he was assassinated in the driveway in 1963. The National Park Service preserves the house; interior visitation is structured around current tour availability rather than unrestricted entry.', 'limited', 'https://www.nps.gov/memy/index.htm', null, 'America/Chicago', now()),
  ('Mississippi Civil Rights Museum', 'mississippi-civil-rights-museum', 'weird-history', 32.30181, -90.17811, 'Jackson', 'MS', 'The state museum devoted to Mississippi''s civil-rights history, including segregation, resistance, organizing, violence and the movement''s major figures. Its central galleries connect many of the individual sites on this list into a broader statewide story.', 'open', 'https://mcrm.mdah.ms.gov/', null, 'America/Chicago', now()),
  ('Smith Robertson Museum and Cultural Center', 'smith-robertson-museum-and-cultural-center', 'weird-history', 32.30541, -90.18677, 'Jackson', 'MS', 'A museum of African American history and culture housed in Jackson''s first public school building for Black children. Exhibits cover slavery, migration, civil rights, Mississippi Black institutions and figures including former student Richard Wright.', 'open', 'https://jacksonms.gov/government/city-departments/human-and-cultural-services/cultural-services/smith-robertson-museum/', null, 'America/Chicago', now()),
  ('Forks of the Road Slave Market Site', 'forks-of-the-road-slave-market-site', 'weird-history', 31.55557, -91.38388, 'Natchez', 'MS', 'The preserved and interpreted location of one of the largest domestic slave markets in the antebellum South. The site is part of Natchez National Historical Park and should be presented directly as a place of enslavement and forced sale, not softened into generic antebellum tourism.', 'open', 'https://www.nps.gov/natc/learn/historyculture/slave-market-at-the-forks-of-the-road.htm', null, 'America/Chicago', now()),
  ('Rhythm Night Club Memorial Museum', 'rhythm-night-club-memorial-museum', 'weird-history', 31.55925, -91.39742, 'Natchez', 'MS', 'A memorial museum at the site of the 1940 Rhythm Night Club fire, one of the deadliest nightclub fires in U.S. history. Exhibits preserve victim names, photographs, recordings and survivor accounts from a tragedy that killed more than 200 people.', 'open', 'https://visitmississippi.org/things-to-do/history/rhythm-night-club-memorial-museum/', 'https://www.rnconsitemm.org/', 'America/Chicago', now()),
  ('Mount Zion United Methodist Church — Freedom Summer Site', 'mount-zion-united-methodist-church-freedom-summer-site', 'weird-history', 32.7821, -88.99152, 'Philadelphia', 'MS', 'The church congregation was attacked and its building burned in 1964 during the campaign that preceded the murders of James Chaney, Andrew Goodman and Michael Schwerner. It remains a religious and memorial site, so visitors should respect church use and current access.', 'limited', 'https://www.nps.gov/subjects/civilrights/mississippi.htm', null, 'America/Chicago', now()),
  ('James Chaney Grave', 'james-chaney-grave', 'weird-history', 32.36431, -88.70366, 'Meridian', 'MS', 'The grave of civil-rights worker James Chaney, murdered in 1964 with Andrew Goodman and Michael Schwerner during Freedom Summer. This is a cemetery memorial stop; visit respectfully and do not treat the grave as spectacle.', 'open', 'https://crdl.usg.edu/', null, 'America/Chicago', now()),
  ('Chaney-Goodman-Schwerner Murder Site Marker', 'chaney-goodman-schwerner-murder-site-marker', 'weird-history', 32.66353, -89.03163, 'Philadelphia', 'MS', 'A roadside historical marker near the rural location where James Chaney, Andrew Goodman and Michael Schwerner were murdered by members of the Ku Klux Klan in June 1964. Stop only where it is safe and lawful to pull off the road.', 'roadside', 'https://www.nps.gov/subjects/civilrights/mississippi.htm', null, 'America/Chicago', now()),
  ('Biloxi Wade-In Memorial', 'biloxi-wade-in-memorial', 'weird-history', 30.39398, -88.90162, 'Biloxi', 'MS', 'A memorial near the Biloxi Lighthouse commemorating Black residents who challenged segregation of the Mississippi Gulf Coast beaches beginning in 1959. The campaign culminated in violent attacks on protesters and became an important Mississippi civil-rights struggle. Secondary source: https://biloxi.ms.us/', 'open', 'https://www.hmdb.org/m.asp?m=243034', null, 'America/Chicago', now()),
  ('COFO Civil Rights Education Center', 'cofo-civil-rights-education-center', 'weird-history', 32.29748, -90.20173, 'Jackson', 'MS', 'The former state headquarters of the Council of Federated Organizations, which coordinated major Mississippi civil-rights campaigns including the 1963 Freedom Vote and 1964 Freedom Summer. Jackson State University operates the restored site as an education center with regular weekday hours.', 'open', 'https://www.jsums.edu/cofo/', null, 'America/Chicago', now()),
  ('Eudora Welty House & Garden', 'eudora-welty-house-garden', 'weird-history', 32.31727, -90.17028, 'Jackson', 'MS', 'The longtime home of writer Eudora Welty, preserved with her books, furnishings, garden and personal environment substantially intact. Guided access is structured around museum hours and tours, making it a strong literary stop rather than a generic historic house.', 'limited', 'https://welty.mdah.ms.gov/', null, 'America/Chicago', now()),
  ('Old Capitol Museum', 'old-capitol-museum', 'weird-history', 32.2981, -90.18, 'Jackson', 'MS', 'Mississippi''s former state capitol, now a museum interpreting the building''s political history and the events that occurred inside it. Its Greek Revival interiors, layered state history and longstanding local ghost stories make it relevant to OddWay, though paranormal claims should remain clearly identified as stories rather than fact.', 'open', 'https://www.mdah.ms.gov/explore-mississippi/old-capitol-museum', null, 'America/Chicago', now()),
  ('Vicksburg National Military Park — Visitor Center', 'vicksburg-national-military-park-visitor-center', 'weird-history', 32.36213, -90.8503, 'Vicksburg', 'MS', 'The main entry point to the vast battlefield landscape surrounding Vicksburg, with earthworks, monuments, artillery positions and preserved siege terrain. The park documents the 1863 campaign whose outcome helped give the Union control of the Mississippi River. Coordinate source: https://www.recreation.gov/gateways/2782', 'open', 'https://www.nps.gov/vick/index.htm', null, 'America/Chicago', now()),
  ('USS Cairo Museum and Gunboat', 'uss-cairo-museum-and-gunboat', 'museums', 32.3758, -90.86649, 'Vicksburg', 'MS', 'The recovered remains of USS Cairo, an ironclad gunboat sunk by electrically detonated mines in 1862 and later raised from the Yazoo River. The preserved vessel and artifacts form one of Mississippi''s strangest large-scale archaeological museum displays.', 'open', 'https://www.nps.gov/vick/learn/historyculture/uss-cairo-gunboat.htm', null, 'America/Chicago', now()),
  ('Vicksburg National Cemetery', 'vicksburg-national-cemetery', 'weird-history', 32.37517, -90.86775, 'Vicksburg', 'MS', 'A vast national cemetery containing the graves of more than 17,000 Union soldiers, many of them unidentified, along with later veterans. It is a powerful physical record of Civil War loss and should be visited as a cemetery and memorial.', 'open', 'https://www.nps.gov/vick/learn/historyculture/national-cemetery.htm', null, 'America/Chicago', now()),
  ('Old Court House Museum', 'old-court-house-museum', 'museums', 32.35205, -90.87862, 'Vicksburg', 'MS', 'An 1858-60 courthouse turned local-history museum, filled with Civil War artifacts, furniture, portraits, tools and other objects tied to Vicksburg''s past. The building itself survived the siege and remains one of the city''s most recognizable historic structures. Coordinate source: National Register documentation', 'open', 'https://oldcourthouse.org/', null, 'America/Chicago', now()),
  ('Biedenharn Coca-Cola Museum', 'biedenharn-coca-cola-museum', 'museums', 32.35172, -90.88165, 'Vicksburg', 'MS', 'A museum in the building where Joseph Biedenharn first bottled Coca-Cola on a large commercial basis in 1894. Vintage advertising, bottling equipment and soda-fountain material make it a compact example of American commercial odd-history.', 'open', 'https://www.biedenharncoca-colamuseum.com/', null, 'America/Chicago', now()),
  ('Jesse Brent Lower Mississippi River Museum', 'jesse-brent-lower-mississippi-river-museum', 'museums', 32.35343, -90.88185, 'Vicksburg', 'MS', 'A free U.S. Army Corps of Engineers museum about the Mississippi River, flood control and river life, including an outdoor scale river model and the retired Motor Vessel Mississippi IV. The combination of engineering history, flood disasters and a walk-through workboat gives it strong OddWay value. Coordinate source: https://www.atlasobscura.com/places/lower-mississippi-river-museum', 'open', 'https://www.mvk.usace.army.mil/Missions/Recreation/Lower-Mississippi-River-Museum/', null, 'America/Chicago', now()),
  ('Vicksburg Riverfront Murals', 'vicksburg-riverfront-murals', 'roadside-oddities', 32.35213, -90.88338, 'Vicksburg', 'MS', 'A long series of large painted panels on the Mississippi River floodwall depicting episodes from Vicksburg''s history, river culture and local legends. The outdoor location makes the murals an easy walkable stop immediately beside downtown river attractions.', 'open', 'https://www.vicksburg.org/things-to-do/attractions/vicksburg-riverfront-murals/', null, 'America/Chicago', now()),
  ('Grand Gulf Military State Park and Ghost Town', 'grand-gulf-military-state-park-and-ghost-town', 'weird-history', 32.04439, -91.0513, 'Port Gibson', 'MS', 'A large historic park preserving the remnants of Grand Gulf, a river town damaged by war and ultimately abandoned after changes to the Mississippi River. Historic buildings, cemetery areas, military earthworks and moved structures create a rare combination of ghost town and museum landscape. Coordinate source: National Register documentation', 'open', 'https://www.grandgulfpark.ms.gov/', null, 'America/Chicago', now()),
  ('Beauvoir', 'beauvoir', 'weird-history', 30.39238, -88.97086, 'Biloxi', 'MS', 'The postwar home of Confederate president Jefferson Davis, now a historic site with a museum, archives, grounds and a Confederate veterans cemetery. OddWay should frame the site within Civil War, Lost Cause and memorial-history context rather than treating Confederate commemoration uncritically.', 'open', 'https://www.visitbeauvoir.org/', null, 'America/Chicago', now()),
  ('Ohr-O''Keefe Museum of Art', 'ohr-okeefe-museum-of-art', 'museums', 30.39361, -88.87167, 'Biloxi', 'MS', 'A Frank Gehry-designed museum campus centered on the wildly experimental ceramic work of Biloxi''s self-described "Mad Potter," George Ohr. The eccentric pottery and unusual architecture make the museum a natural OddWay stop even without paranormal or roadside folklore.', 'open', 'https://georgeohr.org/visit/', null, 'America/Chicago', now()),
  ('Walter Anderson Museum of Art', 'walter-anderson-museum-of-art', 'museums', 30.4105, -88.8275, 'Ocean Springs', 'MS', 'A museum devoted to Walter Inglis Anderson''s highly distinctive paintings, block prints, carvings and coastal imagery. Anderson''s intense relationship with Horn Island and the natural world gives the collection an unusually personal, almost mythic sense of place.', 'open', 'https://www.walterandersonmuseum.org/', null, 'America/Chicago', now()),
  ('Shearwater Pottery', 'shearwater-pottery', 'weird-history', 30.405, -88.82056, 'Ocean Springs', 'MS', 'A family pottery compound founded by Peter Anderson in 1928 and still producing ceramics using long-established forms, glazes and local traditions. The showroom is public while the working property remains an active craft site, so visitors should follow posted access rules.', 'open', 'https://www.shearwaterpottery.com/', null, 'America/Chicago', now()),
  ('Biloxi Lighthouse', 'biloxi-lighthouse', 'roadside-oddities', 30.39442, -88.90122, 'Biloxi', 'MS', 'An 1848 cast-iron lighthouse unusually positioned in the median of U.S. 90 and long used as a symbol of Gulf Coast hurricane survival. Tours operate on a limited schedule and, as of 2026, access to the upper deck is temporarily restricted for repairs.', 'limited', 'https://biloxi.ms.us/visitor-info/museums/lighthouse/', null, 'America/Chicago', now()),
  ('Hurricane Katrina Memorial — Biloxi Town Green', 'hurricane-katrina-memorial-biloxi-town-green', 'weird-history', 30.39333, -88.8864, 'Biloxi', 'MS', 'A memorial dedicated in 2006 to Mississippi Gulf Coast residents killed by Hurricane Katrina. Its black granite wall, wave mosaic and case of storm-recovered personal objects make the scale of the 2005 disaster tangible in the center of Biloxi.', 'open', 'https://discover.biloxi.ms.us/town-green-katrina-memorial/', null, 'America/Chicago', now()),
  ('Maritime & Seafood Industry Museum', 'maritime-seafood-industry-museum', 'museums', 30.39335, -88.85911, 'Biloxi', 'MS', 'A museum covering more than three centuries of Gulf Coast shipbuilding, seafood work, storms and maritime culture. It also houses the Hurricane Camille Memorial, linking everyday coastal industry with one of the region''s most destructive disasters.', 'open', 'https://www.maritimemuseum.org/', null, 'America/Chicago', now()),
  ('Waveland''s Ground Zero Hurricane Museum', 'wavelands-ground-zero-hurricane-museum', 'weird-history', 30.2863, -89.37438, 'Waveland', 'MS', 'A museum in one of the Mississippi communities hit hardest by Hurricane Katrina, preserving photographs, personal accounts, artifacts and recovery stories. Its hurricane simulator and Katrina recovery collections make it both memorial and disaster-history museum.', 'open', 'https://www.wavelandgroundzero.com/', null, 'America/Chicago', now()),
  ('Mississippi Industrial Heritage Museum / Soulé Steam Feed Works', 'mississippi-industrial-heritage-museum-soul-steam-feed-works', 'weird-history', 32.36558, -88.69618, 'Meridian', 'MS', 'A preserved late-19th- and early-20th-century industrial complex filled with belt-driven machinery, foundry equipment and steam-era manufacturing technology. Rather than a reconstructed display, much of the museum occupies the original Soulé factory environment.', 'open', 'https://www.industrialheritagemuseum.com/', null, 'America/Chicago', now()),
  ('Dentzel Carousel', 'dentzel-carousel', 'roadside-oddities', 32.37685, -88.71861, 'Meridian', 'MS', 'A rare 1895 Dentzel menagerie carousel housed in its historic carousel building and long operated as a public attraction in Highland Park. As of September 2026 Visit Meridian lists the carousel as temporarily closed for renovations, so keep it in the database as `limited` until reopening is confirmed.', 'limited', 'https://visitmeridian.com/things_to_do/dentzel-carousel/', null, 'America/Chicago', now()),
  ('Brices Cross Roads National Battlefield Site', 'brices-cross-roads-national-battlefield-site', 'weird-history', 34.50612, -88.72889, 'Baldwyn', 'MS', 'A small National Park Service battlefield site marking the 1864 Battle of Brices Cross Roads. The physical battlefield extends well beyond the monument, but the NPS site gives travelers a reliable, routable anchor for the conflict and its landscape. Coordinate source: https://www.recreation.gov/gateways/2600', 'open', 'https://www.nps.gov/brcr/index.htm', null, 'America/Chicago', now()),
  ('Tupelo National Battlefield', 'tupelo-national-battlefield', 'weird-history', 34.25558, -88.73709, 'Tupelo', 'MS', 'A one-acre National Park Service site marking the July 1864 Battle of Tupelo, where Union forces sought to protect critical railroad supply lines. The compact monument is easy to route and serves as a physical stop for a battle whose wider landscape has largely been absorbed by modern Tupelo. Coordinate source: https://www.recreation.gov/gateways/2959', 'open', 'https://www.nps.gov/tupe/index.htm', null, 'America/Chicago', now()),
  ('Rowan Oak', 'rowan-oak', 'weird-history', 34.35981, -89.52469, 'Oxford', 'MS', 'William Faulkner''s longtime home, preserved by the University of Mississippi with his rooms, grounds and writing environment still central to the visit. The estate gives travelers a direct physical setting for one of the South''s most influential and famously gothic literary imaginations.', 'open', 'https://www.rowanoak.com/', null, 'America/Chicago', now()),
  ('Longwood', 'longwood', 'roadside-oddities', 31.53667, -91.40472, 'Natchez', 'MS', 'The largest octagonal house in the United States, topped by an onion-shaped dome and famously left unfinished when construction stopped during the Civil War. Visitors can tour the finished lower level and the raw upper stories, where building materials and structural framing remain exposed. Secondary source: https://visitmississippi.org/things-to-do/architecture/longwood/', 'open', 'https://natchezpilgrimage.com/year-round/longwood-circa-1860-1861/', null, 'America/Chicago', now()),
  ('Old Biloxi Cemetery', 'old-biloxi-cemetery', 'weird-history', 30.39611, -88.91056, 'Biloxi', 'MS', 'One of the Gulf Coast''s oldest surviving cemeteries, with French-inscribed stones, above-ground tombs, notable coastal figures and visible evidence of repeated hurricane damage and restoration. The cemetery remains active historic ground, so visitors should stay respectful and follow city rules. Secondary source: https://msgulfcoastheritage.ms.gov/historic/sites/old-biloxi-cemetery/', 'open', 'https://discover.biloxi.ms.us/old-biloxi-cemetery/', null, 'America/Chicago', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as mississippi from public.stops where state = 'MS';
